"use client";
/**
 * CopyPlus — a copy button that asks one simple question: copy the text only, or the text and its images (React 18/19, no deps).
 *  Tap the copy icon → a small menu drops down under it: "Text only" (with a preview of the text) and "Text and images"
 *  (with a 2×2 of the images and how many come along). One tap copies; the icon turns into a black tick and, for a moment,
 *  a note says what was copied ("Text copied" / "Copied with 4 images"). Outside click or Esc closes the menu.
 *  "Text and images" puts rich HTML on the clipboard (the text, then the images), so pasting into Docs, Notion, Gmail,
 *  Slack or Word brings the pictures too; plain-text apps get the text and the image links.
 * What you get: the copy button and its menu. backdrop={true} (default) also draws a demo around it — a grey page and a
 *  chat message (the images, a text bubble, "1 hour ago", retry and share icons). That page and message are only the demo
 *  backdrop. backdrop={false} = just the copy button (and its menu), to drop into your own action row.
 * Kit-ready: the CSS lives in this file (scoped under .cpx) and starts with a small kit-shield block.
 */
import { useCallback, useEffect, useRef, useState, type CSSProperties } from "react";

// ---------------------------------------------------------------- types
export type CopyMode = "text" | "all";
export type CopyImage = { src: string; alt?: string };
export type CopyPayload = { mode: CopyMode; text: string; html: string; images: CopyImage[] };
export type CopyPlusLabels = {
  copy: string;                               // the menu's small title, and the button's aria-label
  textOnly: string;
  textAndImages: string;
  imagesCount: (n: number) => string;         // under "Text and images"
  copiedText: string;                         // the note after copying text
  copiedAll: (n: number) => string;           // the note after copying text + images
  failed: string;                             // the note when the browser refuses
};
export type CopyPlusColors = {
  page: string;      // demo page (backdrop only)
  ink: string;       // text, the tick button
  mute: string;      // grey text
  menu: string;      // the menu's surface
  line: string;      // hairlines
  hover: string;     // a row under the pointer
  tile: string;      // image tiles and the T square
};
export type CopyPlusProps = {
  text?: string;                              // what gets copied (and shown in the demo bubble)
  html?: string;                              // optional rich version of the text (defaults to the text in a <p>)
  images?: (string | CopyImage)[];            // the images that come along with "Text and images"
  when?: string;                              // the small grey time before the button ("1 hour ago"); "" for none
  labels?: Partial<CopyPlusLabels>;
  colors?: Partial<CopyPlusColors>;
  align?: "end" | "start";                    // the menu lines up with the row's right edge (end) or the button's left (start)
  noteMs?: number;                            // how long the tick + note stay (1800)
  fontFamily?: string;
  loadFont?: boolean;                         // load Inter from Google Fonts (true)
  backdrop?: boolean;                         // the demo page + chat message around it (true); false = just the button
  simulate?: boolean;                         // demo: opens, points at "Text and images", shows it copied, loops (false)
  autoplay?: boolean;                         // same as simulate (the name live previews and library cards pass); false stops it
  onOpen?: () => void;
  onClose?: () => void;
  onCopy?: (payload: CopyPayload) => void;    // after a successful copy
  onError?: (error: unknown, payload: CopyPayload) => void;
  className?: string;
  style?: CSSProperties;
};

// ---------------------------------------------------------------- defaults (demo content)
const DEMO_TEXT = "Four character sketches for the new avatar set.";
const DEMO_IMAGES = [
  "https://cdn.21st.dev/assets/mirror/df/df407fb6ac9e72efcc1e8a8d2efc31b7fa36d46cbf2ac63efa77e0bc97716cbe.jpg",
  "https://cdn.21st.dev/assets/mirror/88/886945959cb0fc18cd57b99754e96ca605c124fa35533657fabc559b85d54688.jpg",
  "https://cdn.21st.dev/assets/mirror/78/78d5ab72069da4e493a236589ba6ae2a70c78c3496a818ac0d4d21ccacd0278a.jpg",
  "https://cdn.21st.dev/assets/mirror/6e/6e08765a578533529d2ab8cd11200b378b90d3a4f5d0cf5bfcfc0bb24bc5c1db.jpg",
];
const LABELS: CopyPlusLabels = {
  copy: "Copy",
  textOnly: "Text only",
  textAndImages: "Text and images",
  imagesCount: (n) => `${n} image${n === 1 ? "" : "s"} come along`,
  copiedText: "Text copied",
  copiedAll: (n) => `Copied with ${n} image${n === 1 ? "" : "s"}`,
  failed: "Couldn't copy",
};
const COLORS: CopyPlusColors = { page: "#f4f4f5", ink: "#111111", mute: "#8a8a90", menu: "#ffffff", line: "#e6e6e9", hover: "#f4f4f5", tile: "#f1f1f3" };

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" } as Record<string, string>)[c]);

// ---------------------------------------------------------------- icons
const IconCopy = () => (<svg className="cpx-i-copy" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinejoin="round"><rect x="8" y="8" width="12" height="12" rx="3" /><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2" /></svg>);
const IconTick = () => (<svg className="cpx-i-tick" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5" /></svg>);
const IconText = () => (<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M5 7V5h14v2M12 5v14M9 19h6" /></svg>);

// ---------------------------------------------------------------- component
export default function CopyPlus({
  text = DEMO_TEXT, html, images: imagesProp = DEMO_IMAGES, when = "1 hour ago", labels, colors, align = "end", noteMs = 1800,
  fontFamily = "Inter, system-ui, -apple-system, sans-serif", loadFont = true, backdrop = true, simulate = false, autoplay = false,
  onOpen, onClose, onCopy, onError, className, style,
}: CopyPlusProps) {
  const L = { ...LABELS, ...labels }, C = { ...COLORS, ...colors };
  const images: CopyImage[] = imagesProp.map((i) => (typeof i === "string" ? { src: i } : i));
  const [open, setOpen] = useState(false);
  const [done, setDone] = useState(false);
  const [note, setNote] = useState("");
  const [hot, setHot] = useState<CopyMode | null>(null);      // simulate: the row it points at
  // the pictures go in after the first paint: a server render then has no <img>, so React adds no preload links
  // ahead of the component, and thumbnail tools that re-fetch <img> tags (through a proxy) can still read them
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  const rowRef = useRef<HTMLDivElement>(null), btnRef = useRef<HTMLButtonElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const demo = simulate || autoplay;
  const live = useRef(demo);                                 // the demo loop stops for good once someone uses it

  const show = useCallback((v: boolean) => { setOpen(v); if (v) onOpen?.(); else onClose?.(); }, [onOpen, onClose]);
  const flash = useCallback((msg: string) => {
    clearTimeout(timer.current); setNote(msg); setDone(true);
    timer.current = setTimeout(() => setDone(false), noteMs);
  }, [noteMs]);

  const payload = (mode: CopyMode): CopyPayload => {
    const body = html ?? `<p>${esc(text)}</p>`;
    const rich = mode === "all" ? body + images.map((i) => `<img src="${esc(i.src)}" alt="${esc(i.alt || "")}" style="max-width:320px">`).join("") : body;
    return { mode, text, html: rich, images: mode === "all" ? images : [] };
  };

  const copy = async (mode: CopyMode, real = true) => {
    const p = payload(mode);
    show(false);
    if (!real) { flash(mode === "text" ? L.copiedText : L.copiedAll(images.length)); return; }
    const plain = mode === "all" && images.length ? text + "\n" + images.map((i) => i.src).join("\n") : text;
    try {
      const nav = typeof navigator !== "undefined" ? navigator : undefined;
      const CI = typeof window !== "undefined" ? (window as unknown as { ClipboardItem?: typeof ClipboardItem }).ClipboardItem : undefined;
      if (mode === "all" && nav?.clipboard?.write && CI) {
        await nav.clipboard.write([new CI({ "text/html": new Blob([p.html], { type: "text/html" }), "text/plain": new Blob([plain], { type: "text/plain" }) })]);
      } else if (nav?.clipboard?.writeText) {
        await nav.clipboard.writeText(plain);
      } else {
        // very old browsers: a hidden selection
        const ta = document.createElement("textarea"); ta.value = plain; ta.setAttribute("readonly", ""); ta.style.cssText = "position:fixed;opacity:0;pointer-events:none";
        document.body.appendChild(ta); ta.select(); const ok = document.execCommand("copy"); ta.remove();
        if (!ok) throw new Error("copy refused");
      }
      flash(mode === "text" ? L.copiedText : L.copiedAll(images.length));
      onCopy?.(p);
    } catch (e) {
      flash(L.failed); onError?.(e, p);
    }
  };

  // outside click and Esc close the menu
  useEffect(() => {
    if (!open) return;
    const down = (e: PointerEvent) => { if (rowRef.current && !rowRef.current.contains(e.target as Node)) show(false); };
    const key = (e: KeyboardEvent) => { if (e.key === "Escape") { show(false); btnRef.current?.focus(); } };
    addEventListener("pointerdown", down); addEventListener("keydown", key);
    return () => { removeEventListener("pointerdown", down); removeEventListener("keydown", key); };
  }, [open, show]);

  // simulate: open → point at "Text and images" → copied → rest → again (stops once someone touches it)
  useEffect(() => {
    live.current = demo;
    if (!demo) { setOpen(false); setHot(null); return; }
    let t: ReturnType<typeof setTimeout>[] = [];
    const run = () => {
      if (!live.current) return;
      t = [
        setTimeout(() => live.current && setOpen(true), 900),
        setTimeout(() => live.current && setHot("all"), 1700),
        setTimeout(() => { if (!live.current) return; setHot(null); copy("all", false); }, 2700),
        setTimeout(run, 6200),
      ];
    };
    run();
    return () => t.forEach(clearTimeout);
  }, [demo]); // eslint-disable-line react-hooks/exhaustive-deps
  const stopDemo = () => { if (live.current) { live.current = false; setHot(null); } };

  useEffect(() => () => clearTimeout(timer.current), []);

  // Inter, added to <head> once (in an effect, so it is safe on the server)
  useEffect(() => {
    if (!loadFont || typeof document === "undefined" || document.getElementById("cpx-inter")) return;
    const l = document.createElement("link"); l.id = "cpx-inter"; l.rel = "stylesheet";
    l.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap"; document.head.appendChild(l);
  }, [loadFont]);

  const vars = { "--cpx-page": C.page, "--cpx-ink": C.ink, "--cpx-mute": C.mute, "--cpx-menu": C.menu, "--cpx-line": C.line, "--cpx-hover": C.hover, "--cpx-tile": C.tile, fontFamily } as CSSProperties;
  const cols = images.length <= 4 ? 2 : 3;

  const control = (
    <div className={`cpx-row${align === "start" ? " cpx-start" : ""}`} ref={rowRef}>
      <span className={`cpx-when${done ? " on" : ""}${when ? "" : " solo"}`} aria-live="polite">
        {when && <span className="cpx-t">{when}</span>}
        <span className="cpx-n">{done ? note : ""}</span>
      </span>
      <button ref={btnRef} type="button" className={`cpx-ib cpx-copy${done ? " done" : ""}`} aria-label={L.copy} aria-haspopup="menu" aria-expanded={open}
        onClick={() => { stopDemo(); show(!open); }}>
        <IconCopy /><IconTick />
      </button>
      {backdrop && (<>
        <button type="button" className="cpx-ib" aria-label="Retry"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round"><path d="M4 12a8 8 0 1 0 2.3-5.6M4 4v4h4" /></svg></button>
        <button type="button" className="cpx-ib" aria-label="Share"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M14 4h6v6M20 4l-8 8M10 6H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-4" /></svg></button>
      </>)}
      <div className={`cpx-menu${open ? " on" : ""}`} role="menu" aria-label={L.copy}>
        <p className="cpx-mt">{L.copy}</p>
        <button type="button" role="menuitem" className={`cpx-it${hot === "text" ? " hot" : ""}`} onClick={() => { stopDemo(); copy("text"); }}>
          <span className="cpx-lead"><IconText /></span>
          <span className="cpx-tx"><b>{L.textOnly}</b><small>“{text}”</small></span>
        </button>
        <button type="button" role="menuitem" className={`cpx-it${hot === "all" ? " hot" : ""}`} onClick={() => { stopDemo(); copy("all"); }}>
          <span className="cpx-mini">{images.slice(0, 4).map((im, i) => <i key={i}>{mounted && <img src={im.src} alt="" />}</i>)}</span>
          <span className="cpx-tx"><b>{L.textAndImages}</b><small>{L.imagesCount(images.length)}</small></span>
        </button>
      </div>
    </div>
  );

  return (
    <div className={`cpx${backdrop ? " cpx-bd" : ""}${className ? " " + className : ""}`} style={{ ...vars, ...style }}>
      <style>{CSS}</style>
      {backdrop ? (
        <div className="cpx-msg">
          <div className="cpx-grid" style={{ gridTemplateColumns: `repeat(${cols}, 1fr)` }}>
            {images.map((im, i) => <div key={i}>{mounted && <img src={im.src} alt={im.alt || ""} />}</div>)}
          </div>
          <div className="cpx-bubble">{text}</div>
          {control}
        </div>
      ) : control}
    </div>
  );
}

// ---------------------------------------------------------------- styles
const CSS = `/* kit-shield: undo Tailwind preflight inside the component (Kit) */
:where(.cpx) { line-height: normal; color: CanvasText; tab-size: 8; font-feature-settings: normal; font-variation-settings: normal; -webkit-text-size-adjust: auto; -webkit-tap-highlight-color: initial; }
:where(.cpx) :where(*), :where(.cpx) :where(*)::before, :where(.cpx) :where(*)::after { box-sizing: revert; margin: revert; padding: revert; border-width: revert; border-style: revert; border-color: revert; outline-color: revert; }
:where(.cpx) :where(ol, ul, menu) { list-style: revert; }
:where(.cpx) :where(h1, h2, h3, h4, h5, h6) { font-size: revert; font-weight: revert; }
:where(.cpx) :where(a) { color: revert; text-decoration: revert; }
:where(.cpx) :where(b, strong) { font-weight: revert; }
:where(.cpx) :where(small, sub, sup) { font-size: revert; }
:where(.cpx) :where(code, kbd, samp, pre) { font-family: revert; font-size: revert; font-feature-settings: revert; font-variation-settings: revert; }
:where(.cpx) :where(img, svg, video, canvas, audio, iframe, embed, object) { display: revert; vertical-align: revert; }
:where(.cpx) :where(img, video) { max-width: revert; height: revert; }
:where(.cpx) :where(button, input, select, optgroup, textarea) { font: revert; letter-spacing: revert; color: revert; border-radius: revert; background-color: revert; opacity: revert; }
:where(.cpx) :where(button, input[type="button"], input[type="reset"], input[type="submit"]) { appearance: revert; }
:where(.cpx) :where(textarea) { resize: revert; }
:where(.cpx) :where(table) { text-indent: revert; border-color: revert; border-collapse: revert; }
:where(.cpx) :where(summary) { display: revert; }
:where(.cpx) ::placeholder { color: revert; opacity: revert; }
.cpx { position: relative; display: inline-block; color: var(--cpx-ink); -webkit-font-smoothing: antialiased; }
.cpx button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: left; }

/* the demo page and message (backdrop only) */
.cpx-bd { display: flex; justify-content: center; align-items: center; width: 100%; min-height: 720px; padding: 40px 16px 190px; box-sizing: border-box; background: var(--cpx-page); }
.cpx-msg { display: flex; flex-direction: column; align-items: flex-end; width: 380px; max-width: 100%; }
.cpx-grid { display: grid; gap: 6px; width: 100%; }
.cpx-grid div { aspect-ratio: 1; border-radius: 16px; background: #e9e9eb; overflow: hidden; }
.cpx-grid img { display: block; width: 100%; height: 100%; object-fit: cover; }
.cpx-bubble { margin-top: 8px; padding: 9px 15px; border-radius: 18px; background: var(--cpx-menu); font-size: 15px; line-height: 1.4; box-shadow: 0 0 0 1px #e9e9ec; }

/* the action row: time, the copy button (and in the demo, retry + share) */
.cpx-row { position: relative; display: flex; align-items: center; gap: 2px; height: 34px; font-size: 13px; color: var(--cpx-mute); }
.cpx-bd .cpx-row { margin-top: 8px; }
.cpx-ib { position: relative; width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; color: #55555b; transition: background .15s, color .15s; }
.cpx-ib:hover, .cpx-ib[aria-expanded="true"] { background: #e8e8ea; color: var(--cpx-ink); }
.cpx-ib:focus-visible { outline: 2px solid var(--cpx-ink); outline-offset: 1px; }
.cpx-copy.done { background: var(--cpx-ink); color: #fff; }
.cpx-copy svg { transition: opacity .15s, transform .25s cubic-bezier(.3,1.3,.4,1); }
.cpx-i-tick { position: absolute; opacity: 0; transform: scale(.5); }
.cpx-copy.done .cpx-i-tick { opacity: 1; transform: none; }
.cpx-copy.done .cpx-i-copy { opacity: 0; transform: scale(.5); }

/* "1 hour ago" ⇄ what was copied */
.cpx-when { display: grid; justify-items: end; margin-right: 8px; }
.cpx-when.solo { position: absolute; right: calc(100% + 8px); margin: 0; }
.cpx-when > span { grid-area: 1 / 1; white-space: nowrap; transition: opacity .2s, transform .25s; }
.cpx-n { color: var(--cpx-ink); font-weight: 500; opacity: 0; transform: translateY(4px); }
.cpx-when.on .cpx-t { opacity: 0; transform: translateY(-4px); }
.cpx-when.on .cpx-n { opacity: 1; transform: none; }

/* the drop-down */
.cpx-menu { position: absolute; top: 40px; right: 0; width: 272px; padding: 6px; box-sizing: border-box; border-radius: 18px; background: var(--cpx-menu); box-shadow: 0 0 0 1px var(--cpx-line); color: var(--cpx-ink); z-index: 20;
  opacity: 0; transform: translateY(-6px) scale(.97); transform-origin: top right; pointer-events: none; transition: opacity .16s, transform .24s cubic-bezier(.3,1.2,.4,1); }
.cpx-start .cpx-menu { right: auto; left: 0; transform-origin: top left; }
.cpx-menu.on { opacity: 1; transform: none; pointer-events: auto; }
.cpx-mt { margin: 0; padding: 8px 10px 6px; font-size: 12.5px; line-height: 1.3; color: var(--cpx-mute); }
.cpx .cpx-it { width: 100%; display: flex; align-items: center; gap: 12px; padding: 9px 10px; box-sizing: border-box; border-radius: 12px; transition: background .12s; }
.cpx-it:hover, .cpx-it.hot, .cpx-it:focus-visible { background: var(--cpx-hover); outline: 0; }
.cpx-lead { flex: none; width: 36px; height: 36px; border-radius: 10px; background: var(--cpx-tile); display: grid; place-items: center; color: var(--cpx-ink); }
.cpx-tx { min-width: 0; }
.cpx-tx b { display: block; font-size: 14.5px; font-weight: 500; line-height: 1.3; }
.cpx-tx small { display: block; margin-top: 2px; font-size: 12.5px; line-height: 1.3; color: var(--cpx-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cpx-mini { flex: none; width: 36px; height: 36px; padding: 3px; box-sizing: border-box; border-radius: 10px; background: var(--cpx-tile); display: grid; grid-template-columns: 1fr 1fr; gap: 2px; }
.cpx-mini i { display: block; border-radius: 4px; background: #fff; overflow: hidden; }
.cpx-mini img { display: block; width: 100%; height: 100%; object-fit: cover; }
@media (prefers-reduced-motion: reduce) { .cpx-menu, .cpx-when > span, .cpx-copy svg { transition: none; } }
`;

